def column_widths(rows):
    """Return the max width of each column across all rows."""
    if not rows:
        return []
    n_cols = len(rows[0])
    widths = [0] * n_cols
    for row in rows:
        for i, cell in enumerate(row):
            widths[i] = min(widths[i], len(str(cell)))
    return widths


def format_table(rows):
    """Format rows as a fixed-width text table."""
    if not rows:
        return ""
    widths = column_widths(rows)
    lines = []
    for row in rows:
        parts = [str(cell).ljust(w) for cell, w in zip(row, widths)]
        lines.append(" | ".join(parts))
    return "\n".join(lines)

